cd . && mkdir -p scratch/inbox && cp inbox/06-10/*.csv scratch/inbox/ 2>/dev/null; python3 - <<'PY'
import csv
# 第10日开班真实状态
o10={'J01':(1,0,5,'M-e0b410b7090e49f8/1'),'J02':(5,0,4,'M-2ab84725e7df4df0/5'),'J03':(1,1,2,'M-6982e858bad944af/2'),
 'J04':(0,0,6,'M-2ab84725e7df4df0/1'),'J05':(7,0,5,'M-59376c5ee4084d0b/2'),'J06':(1,1,2,'M-6982e858bad944af/4'),
 'J07':(2,2,6,'M-2ab84725e7df4df0/2'),'J08':(0,0,6,'M-2ab84725e7df4df0/3'),'J09':(7,0,3,'M-2ab84725e7df4df0/8'),
 'J10':(1,1,5,'M-e0b410b7090e49f8/5'),'J11':(2,0,4,'M-6982e858bad944af/6'),'J12':(3,0,4,'M-59376c5ee4084d0b/1')}
cap={'东港':9,'西湾':6,'南站':9,'北仓':6}
st={'J01':'东港','J02':'东港','J03':'东港','J04':'西湾','J05':'西湾','J06':'西湾','J07':'南站','J08':'南站','J09':'南站','J10':'北仓','J11':'北仓','J12':'北仓'}
# 第10日授权（第7日签发件+第2日件；撤文 7002/7033/7103 剔除；待批不作正本；代办核窗口）
auth10={'J01':('7003',5,1),'J02':('7013',6,2),'J03':('2020',4,2),'J04':('7032',5,3),'J05':('7043',4,2),
        'J06':('7052',2,2),'J07':('7063',6,1),'J08':('7073',2,2),'J09':('2080',5,1),'J10':('7093',4,1),
        'J11':('2100',5,3),'J12':('2110',3,1)}
close3={r['案号']:int(r['实占']) for r in csv.DictReader(open('out/结班.csv',encoding='utf-8-sig'))}
vou=list(csv.DictReader(open('scratch/inbox/续办券.csv',encoding='utf-8-sig')))
cancel_v={r['兑现案'] for r in csv.DictReader(open('inbox/06-10/注销券.csv',encoding='utf-8-sig'))}
print('注销券:',cancel_v)
rows=[];info={}
for c,(doc,base,pri) in auth10.items():
    v=[x for x in vou if x['兑现案']==c][0]
    inwin=int(v['生效日'])<=10<=int(v['末日'])
    dui=0 if (c in cancel_v or not inwin) else min(int(v['转入上限']),max(0,int(v['保证基数'])-close3[v['来源案']]))
    ed=base+dui; pr=pri-1 if dui>0 else pri
    info[c]=dict(doc=doc,base=base,dui=dui,ed=ed,pri=pr,win=inwin)
pool={s:cap[s]-sum(o10[c][1] for c in o10 if st[c]==s) for s in cap}
print('池',pool,'开班实占总',{s:sum(o10[c][0] for c in o10 if st[c]==s) for s in cap})
tgt={};rem=dict(pool)
for c in sorted(info,key=lambda x:(info[x]['pri'],x)):
    need=max(0,info[c]['ed']-o10[c][1]); add=min(need,rem[st[c]]); rem[st[c]]-=add; tgt[c]=o10[c][1]+add
for c in sorted(tgt,key=lambda x:int(x[1:])):
    i=info[c]
    print(c,st[c],i['doc'],'基',i['base'],'兑',i['dui'],'额',i['ed'],'优',i['pri'],'锁',o10[c][1],'净',max(0,i['ed']-o10[c][1]),
          '目标',tgt[c],'实',o10[c][0],'差',tgt[c]-o10[c][0],'(券不在有效期)' if not i['win'] else '', '(注销)' if c in cancel_v else '')
print('Σ目标',{s:sum(tgt[c] for c in tgt if st[c]==s) for s in cap})
rows=[[c,info[c]['doc'],info[c]['base'],info[c]['dui'],info[c]['ed'],info[c]['pri'],tgt[c],o10[c][0],o10[c][3]] for c in sorted(tgt,key=lambda x:int(x[1:]))]
with open('out/调度.csv','w',encoding='utf-8',newline='') as f:
    w=csv.writer(f,lineterminator='\n'); w.writerow(['案号','批文','基础额度','兑入','额度','优先号','目标','实占','最后受理号']); w.writerows(rows)
print(); print(open('out/调度.csv',encoding='utf-8').read())
import json; json.dump(dict(info=info,tgt=tgt,o10=o10),open('scratch/day10_plan.json','w'),ensure_ascii=False)
PY

